export const MONUMENTS = JSON.parse("[{\"id\":\"n747744042\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Д. Д. Шостакович\",\"x\":-2290,\"z\":-3297.3,\"subject\":\"Q80135\"},{\"id\":\"n3614187009\",\"kind\":\"artwork\",\"name\":\"Композиторы\",\"x\":-2101.4,\"z\":-3418.9},{\"id\":\"n4496341907\",\"kind\":\"artwork\",\"name\":\"Скрипка-сфинкс\",\"x\":-2096.8,\"z\":-3440.9},{\"id\":\"n4496341909\",\"kind\":\"artwork\",\"name\":\"Скрипка-яблоко\",\"x\":-2120.5,\"z\":-3456.8},{\"id\":\"n4975667270\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. М. Кирову\",\"x\":-2050.8,\"z\":-3345.2,\"subject\":\"Q207682\",\"inscription\":\"В этом доме в 1926–1934 годах жил Сергей Миронович Киров\"},{\"id\":\"n5931568248\",\"kind\":\"artwork\",\"x\":-2116.8,\"z\":-3437.5},{\"id\":\"n6837973312\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Скрипка-туфелька\",\"x\":-2155.7,\"z\":-3425.8},{\"id\":\"n6837973313\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Скрипка-граммофон\",\"x\":-2164,\"z\":-3444.6},{\"id\":\"n6837973645\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Скрипка-кресло\",\"x\":-2171.7,\"z\":-3428.4},{\"id\":\"n9014803616\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. С. Вивьену\",\"x\":-2288.9,\"z\":-3418.6,\"subject\":\"Q4110524\",\"inscription\":\"В этом доме с 1958 по 1966 год жил Народный артист СССР, лауреат Государственной премии СССР профессор Леонид Сергеевич Вивьен\"},{\"id\":\"n9822832283\",\"kind\":\"artwork\",\"sub\":\"bust\",\"name\":\"Дмитрий Дмитриевич Шостакович\",\"x\":-2281.5,\"z\":-3395.4},{\"id\":\"n10977225339\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Кузнецову\",\"x\":-2312,\"z\":-3315.4,\"inscription\":\"В этом доме с 1937 года по 1946 год жил Алексей Александрович Кузнецов, партийный и государственный деятель, один из руководителей обороны Ленинграда в годы Великой Отечественной войны\"},{\"id\":\"n10977225343\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. К. Черкасову\",\"x\":-2265.9,\"z\":-3248.1,\"inscription\":\"Выдающийся деятель советского искусства, Народный артист СССР Николай Константинович Черкасов жил в этом доме с 1944 года по 1966 год\"},{\"id\":\"n11573386858\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. А. Говорову\",\"x\":-2287.6,\"z\":-3277.8},{\"id\":\"n13120961394\",\"kind\":\"artwork\",\"sub\":\"mural\",\"x\":-2218.9,\"z\":-3348.4,\"subject\":\"Шостакович, Дмитрий Дмитриевич\"},{\"id\":\"n4799913762\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Пётр I\",\"x\":-1800.3,\"z\":-3273.8,\"subject\":\"Q8479\",\"inscription\":\"Петербург 2003\"},{\"id\":\"n4846090608\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Вернадскому\",\"x\":-2027.7,\"z\":-3365.7,\"subject\":\"Q316371\",\"inscription\":\"Здесь работал в 1922–1938 гг. великий ученый мыслитель естествоиспытатель основатель радиевого института академик Владимир Иванович Вернадский\"},{\"id\":\"n4846092600\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Г. Хлопину\",\"x\":-2031,\"z\":-3372.8,\"subject\":\"Q4498148\",\"inscription\":\"Здесь работал в 1922–1950 гг выдающийся ученый основоположник советской радиохимии директор радиевого института в 1939–1950 гг. академик Виталий Григорьевич Хлопин\"},{\"id\":\"n5195119079\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"В. И. Ленин\",\"x\":-1986.2,\"z\":-3312.5,\"subject\":\"Q1394\"},{\"id\":\"n8807564639\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Мыльникову\",\"x\":-2063.1,\"z\":-3368.5,\"subject\":\"Q3740994\",\"inscription\":\"В этом доме с 1951 по 1967 г.г. жил и работал народный художник Андрей Андреевич Мыльников\"},{\"id\":\"n8807583500\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. Ф. Фёдорову\",\"x\":-2072.1,\"z\":-3387.1,\"subject\":\"Q65154676\",\"inscription\":\"В этом доме с 1924 по 1926 год жил Григорий Федорович Федоров, питерский рабочий-революционер, с 1907 года член большевистской партии, в 1917 году - член ЦК и Петербургского комитета РСДРП(б), председатель центрального совета фабзавкомов, ...\"},{\"id\":\"n8807583640\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. П. Костенко\",\"x\":-2021.3,\"z\":-3262.5,\"subject\":\"Q4235318\",\"inscription\":\"В этом доме с 1947 года по 1956 год жил выдающийся кораблестроитель Владимир Полиевктович Костенко\"},{\"id\":\"n13333975428\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1791.8,\"z\":-3277.9},{\"id\":\"n4496341906\",\"kind\":\"artwork\",\"x\":-2120.8,\"z\":-3489},{\"id\":\"n12206166629\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Вермишеву\",\"x\":-2306.9,\"z\":-3558.7,\"subject\":\"Q4107887\"},{\"id\":\"n292325680\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Низами Гянджеви\",\"x\":-2060.1,\"z\":-3497,\"h\":5,\"material\":\"bronze\",\"startDate\":\"2002\",\"artist\":\"Геруш Бабаев\",\"wikidata\":\"Q2817285\",\"wikipedia\":\"ru:Памятник Низами Гянджеви (Санкт-Петербург)\"},{\"id\":\"n2758253373\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"В. К. Рентген\",\"x\":-1840.4,\"z\":-3481.5,\"material\":\"bronze\",\"startDate\":\"1928-02-17\",\"subject\":\"Q35149\"},{\"id\":\"n11569265080\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"3-я гвардейская стрелковая дивизия народного ополчения\",\"x\":-940,\"z\":-3301.4,\"subject\":\"3-я гвардейская стрелковая дивизия народного ополчения\"}]");
